// Accio Hub P0.3 — protótipo independente, sem backend nem acesso aos serviços reais.
const KEY = 'accio-hub-p0.3-studio';
const previous = (()=>{try{return JSON.parse(localStorage.getItem('accio-hub-p0-v1')||'{}')}catch{return {}}})();
const saved = (()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch{return {}}})();
const projectDefs = [
  {name:'AccioCAD', description:'Geometria, memorial e validação profissional.',icon:'code',tint:'mint'},
  {name:'Accio Hub', description:'Seu espaço pessoal em construção.',icon:'grid',tint:'pink'},
  {name:'Faculdade', description:'Aprendizado, notas e sessões de estudo.',icon:'book',tint:'purple'},
  {name:'AccioFeed', description:'Curadoria de tecnologia e desenvolvimento.',icon:'rss',tint:'orange'}
];
const defaultTasks=[
  {id:1,title:'Validar melhorias do AccioCAD',project:'AccioCAD',done:false,priority:'Normal'},
  {id:2,title:'Estudar arquitetura de computadores',project:'Faculdade',done:false,priority:'Alta'},
  {id:3,title:'Refinar o visual do Accio Hub',project:'Accio Hub',done:false,priority:'Normal'},
  {id:4,title:'Organizar referências de estudo',project:'Faculdade',done:true,priority:'Normal'}
];
const defaultNotes=[
  {id:1,title:'Ideias para o Accio Hub',project:'Accio Hub',body:'# Ideias para o Accio Hub\n\n## Interface\n\n- Dock de aplicativos\n- Widgets ajustáveis\n- Personalização de temas\n\n## Próximos passos\n\nValidar a interface P0.3.'},
  {id:2,title:'Arquitetura de computadores',project:'Faculdade',body:'# Arquitetura de Computadores\n\n## Fundamentos\n\n- CPU e registradores\n- Memória\n- Conversão de bases\n\n[[Sistema binário]]'}
];
const widgetDefs={tasks:{title:'Tarefas em andamento',icon:'check',tint:'mint',span:5},focus:{title:'Focus session',icon:'target',tint:'purple',span:3},calendar:{title:'Agenda',icon:'calendar',tint:'blue',span:4},feed:{title:'AccioFeed',icon:'rss',tint:'orange',span:5},notes:{title:'Seu conhecimento',icon:'book',tint:'pink',span:4},backup:{title:'Backups',icon:'cloud',tint:'blue',span:3},projects:{title:'Projetos ativos',icon:'grid',tint:'mint',span:12}};
const defaultWidgets=Object.entries(widgetDefs).map(([id,x])=>({id,span:x.span,visible:true}));
const state={
  theme:'dark',wallpaper:'northern',accent:'#b1f07d',density:'comfortable',edit:false,
  music:true,musicExpanded:false,focusMin:25,focusLeft:1500,focusRunning:false,focusEnd:null,focusRuns:0,
  page:'home',widgets:defaultWidgets,tasks:previous.tasks||defaultTasks,notes:previous.notes||defaultNotes,
  noteId:1,modal:null,drawer:false,search:false,query:'',project:'AccioCAD',projectTab:'overview',
  ...saved
};
if(!Array.isArray(state.widgets)||!state.widgets.length)state.widgets=defaultWidgets.map(x=>({...x}));
for(const id of Object.keys(widgetDefs))if(!state.widgets.some(w=>w.id===id))state.widgets.push({id,span:widgetDefs[id].span,visible:true});
if(!Array.isArray(state.tasks))state.tasks=defaultTasks;
if(!Array.isArray(state.notes))state.notes=defaultNotes;
state.edit=false; state.modal=null; state.drawer=false; state.search=false;
const esc=x=>String(x??'').replace(/[&<>"']/g,k=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[k]));
const $=q=>document.querySelector(q);
const persist=()=>{const copy={...state,edit:false,modal:null,drawer:false,search:false,query:''};try{localStorage.setItem(KEY,JSON.stringify(copy))}catch(e){console.warn('Persistência local indisponível neste contexto de navegação.')}};
const icons={
  home:'<path d="m3 10 9-7 9 7v10H3V10Z"/><path d="M9 20v-7h6v7"/>',
  grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  check:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="m8 12 3 3 5-6"/>',
  book:'<path d="M12 6C9 4 6 4 3 5v15c3-1 6-1 9 1 3-2 6-2 9-1V5c-3-1-6-1-9 1Z"/><path d="M12 6v15"/>',
  target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
  rss:'<path d="M4 11c5 0 9 4 9 9M4 5c9 0 15 6 15 15"/><circle cx="5" cy="19" r="1"/>',
  cloud:'<path d="M6 18a4 4 0 0 1-1-7.9 7 7 0 0 1 13.1-.4A4.3 4.3 0 0 1 18 18H6Z"/><path d="m9 14 3 3 3-3M12 17v-7"/>',
  mail:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/>',
  inbox:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M3 13h5l2 3h4l2-3h5"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2"/>',
  search:'<circle cx="10.8" cy="10.8" r="7"/><path d="m16 16 5 5"/>',
  edit:'<path d="m4 16 12-12 4 4L8 20H4v-4Z"/>',
  plus:'<path d="M12 4v16M4 12h16"/>',
  play:'<path d="m8 5 11 7-11 7V5Z"/>',
  pause:'<path d="M8 5v14M16 5v14"/>',
  music:'<path d="M9 18V5l12-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="18" cy="16" r="3"/>',
  link:'<path d="M7 17 17 7M8 7h9v9"/>',
  move:'<path d="M12 3v18M3 12h18m-4-4 4 4-4 4M8 7l4-4 4 4M7 16l-4-4 4-4M8 17l4 4 4-4"/>',
  sliders:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="2"/><circle cx="15" cy="17" r="2"/>',
  x:'<path d="M5 5 19 19M19 5 5 19"/>',
  layers:'<path d="m12 3 10 6-10 6L2 9l10-6ZM2 14l10 6 10-6"/>',
  clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
  code:'<path d="m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18"/>',
  dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
  chevron:'<path d="m9 6 6 6-6 6"/>'
};
const icon=(id,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${icons[id]||icons.grid}</svg>`;
const nav=[['home','Início','home'],['tasks','Tarefas','check'],['calendar','Agenda','calendar'],['focus','Foco','target'],['projects','Projetos','grid'],['knowledge','Conhecimento','book'],['feed','AccioFeed','rss'],['backup','Backups','cloud'],['email','E-mails','mail']];
const dock=[['tasks','Tarefas','check','mint'],['calendar','Calendário','calendar','blue'],['focus','Foco','target','purple'],['knowledge','Vault','book','pink'],['projects','Projetos','grid','gold'],['feed','AccioFeed','rss','orange'],['backup','Backups','cloud','blue'],['email','E-mails','mail','pink']];
if(!Array.isArray(state.dockOrder)||state.dockOrder.length===0)state.dockOrder=dock.map(x=>x[0]);
if(!Array.isArray(state.dockHidden))state.dockHidden=[];
const labels={home:'Meu espaço',tasks:'Tarefas',calendar:'Agenda',focus:'Foco',projects:'Projetos',knowledge:'Conhecimento',feed:'AccioFeed',backup:'Backups',email:'E-mails',settings:'Configurações'};
const dateFmt=()=>new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
const timeFmt=()=>new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date());
const fmt=s=>`${String(Math.floor(Math.max(0,s)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,s)%60)).padStart(2,'0')}`;
function syncFocus(){if(state.focusRunning&&state.focusEnd){state.focusLeft=Math.max(0,Math.ceil((state.focusEnd-Date.now())/1000));if(state.focusLeft===0){state.focusRunning=false;state.focusEnd=null;state.focusRuns++;persist();render();}}}
const badge=(txt,type='')=>`<span class="badge ${type}">${esc(txt)}</span>`;
function taskRow(t,quick=true){return `<div class="task-item ${t.done?'is-done':''}"><label class="task-label"><input type="checkbox" data-task="${t.id}" ${t.done?'checked':''}><span class="task-name">${esc(t.title)}<small>${esc(t.project)}${t.priority==='Alta'?' · Alta prioridade':''}</small></span></label>${quick?`<button class="task-play tip" title="Abrir foco" data-route="focus">${icon('play',15)}</button>`:''}</div>`}
function card(id,inner){const d=widgetDefs[id];const w=state.widgets.find(x=>x.id===id);return `<section class="panel panel-${id} span-${w.span} ${state.edit?'editing':''}" data-widget="${id}" draggable="${state.edit}" aria-label="Widget ${d.title}"><div class="panel-top"><div class="panel-heading"><span class="widget-icon tint-${d.tint}">${icon(d.icon,18)}</span><h3>${d.title}</h3></div><div class="panel-controls">${state.edit?`<button class="mini-control" data-zoom="${id}" title="Alternar tamanho">↔</button><button class="mini-control handle" aria-label="Arraste para organizar" title="Arraste este widget">${icon('move',17)}</button>`:widgetAction(id)}</div></div>${inner}</section>`}
const widgetAction=id=>({tasks:`<button class="quiet-link" data-route="tasks">Ver tudo ${icon('link',14)}</button>`,focus:badge('POMODORO'),calendar:`<button class="quiet-link" data-route="calendar">Abrir ${icon('link',14)}</button>`,feed:`<button class="quiet-link" data-route="feed">Ler feed ${icon('link',14)}</button>`,notes:`<button class="quiet-link" data-route="knowledge">Biblioteca ${icon('link',14)}</button>`,backup:badge('NÃO CONECTADO','warn'),projects:`<button class="quiet-link" data-route="projects">Explorar ${icon('link',14)}</button>`})[id];
function widgetContent(id){if(id==='tasks'){const left=state.tasks.filter(t=>!t.done),done=state.tasks.length-left.length;return `<div class="task-stat"><strong>${left.length.toString().padStart(2,'0')}</strong><span>tarefas para fazer <em>${done} concluída(s)</em></span></div><div class="tasks-in-card">${left.slice(0,4).map(t=>taskRow(t)).join('')||'<p class="muted">Seu dia está livre por enquanto.</p>'}</div><button class="add-row" data-modal="task">${icon('plus',15)} Adicionar tarefa</button>`}
if(id==='focus'){const pct=(1-state.focusLeft/(state.focusMin*60))*100;return `<div class="focus-body"><div class="dial" style="--p:${Math.min(100,Math.max(0,pct))}%"><div class="dial-inner"><small>SESSÃO DE FOCO</small><strong data-timer>${fmt(state.focusLeft)}</strong><span>Estude no seu ritmo</span></div></div><div class="focus-actions"><button class="round-btn primary-action" data-action="focus-toggle" title="${state.focusRunning?'Pausar':'Iniciar'}">${icon(state.focusRunning?'pause':'play',20)}</button><button class="round-btn" data-action="focus-reset" title="Reiniciar">↻</button><button class="round-btn" data-action="focus-length" title="Alternar 25/45 minutos">${state.focusMin}m</button></div></div>`}
if(id==='calendar'){return `<div class="calendar-preview"><div class="calendar-track"><span>HOJE</span><div class="calendar-event"><i class="event-dot"></i><div><strong>Organizar ideias</strong><small>Atividade ilustrativa · 19:30</small></div></div><div class="calendar-event"><i class="event-dot purple-dot"></i><div><strong>Sessão de estudos</strong><small>Atividade ilustrativa · 20:30</small></div></div></div><div class="calendar-note">Prévia visual · agenda ainda não conectada</div></div>`}
if(id==='feed'){return `<div class="feed-stack"><div class="featured-story"><div class="story-symbol">${icon('rss',28)}</div><div><div class="overline">RADAR DE TECNOLOGIA / EXEMPLO</div><h4>As ideias que merecem sua atenção.</h4><p>Suas fontes favoritas estarão aqui quando conectarmos o AccioFeed.</p></div></div><div class="feed-micro"><span class="micro-dot orange"></span> Inteligência artificial <span>· artigo ilustrativo</span></div><div class="feed-micro"><span class="micro-dot cyan"></span> Linux &amp; Open Source <span>· artigo ilustrativo</span></div></div>`}
if(id==='notes'){return `<div class="notes-grid">${state.notes.slice(-3).reverse().map((n,i)=>`<button class="note-preview" data-note="${n.id}"><span class="note-preview-top">${icon('book',16)} ${esc(n.project)}</span><strong>${esc(n.title)}</strong><span class="note-open">Abrir nota ${icon('chevron',14)}</span></button>`).join('')}</div><button class="text-action" data-modal="note">${icon('plus',15)} Capturar ideia</button>`}
if(id==='backup'){return `<div class="backup-wait"><span class="backup-pulse">${icon('cloud',32)}</span><div><strong>Aguardando monitor</strong><p>Dados reais serão exibidos após conectar seus scripts.</p></div></div><div class="backup-lines"><span>Local <b>—</b></span><span>Google Drive <b>—</b></span><span>Integridade <b>—</b></span></div>`}
if(id==='projects'){return `<div class="project-strip">${projectDefs.map(p=>`<button class="mini-project" data-open-project="${esc(p.name)}"><span class="project-logo tint-${p.tint}">${icon(p.icon,22)}</span><span><strong>${esc(p.name)}</strong><small>${state.tasks.filter(t=>t.project===p.name&&!t.done).length} tarefa(s) abertas</small></span>${icon('chevron',16)}</button>`).join('')}</div>`}
return ''}
function board(){const open=state.tasks.filter(x=>!x.done).length;return `<div class="board"><div class="board-titleline"><div><div class="eyebrow"><span class="tiny-light"></span> BOARD 01 <span class="eyebrow-sep">/</span> INÍCIO</div><h1>Seu espaço<span class="title-stop">.</span></h1><p>Organização, informação e um pouco de inspiração.</p></div><div class="board-clock"><span data-now-time>${timeFmt()}</span><small data-now-date>${dateFmt()}</small></div></div>
<div class="board-toolbar"><span class="board-count"><b>${open}</b> pendente${open===1?'':'s'} no radar <span class="separator">/</span> <b>${projectDefs.length}</b> projetos</span><div class="toolbar-actions"><span class="demo-chip">PRÉVIA P0.3 · DADOS ILUSTRATIVOS</span><button class="button tertiary" data-action="open-customize">${icon('sliders',17)} Aparência</button><button class="button ${state.edit?'selected':''}" data-action="edit">${icon(state.edit?'check':'move',17)} ${state.edit?'Concluir edição':'Organizar board'}</button></div></div>
<div class="dock-box"><div class="section-label"><span>APLICATIVOS</span><span>SEUS ATALHOS</span></div><div class="app-dock">${state.dockOrder.filter(id=>!state.dockHidden.includes(id)).map(id=>{const d=dock.find(x=>x[0]===id);if(!d)return "";const [key,label,ic,tint]=d;return `<button class="dock-tile ${state.edit?'dock-edit':''}" data-route="${key}" data-dock="${key}" draggable="${state.edit}" title="${state.edit?'Arraste para reorganizar':'Abrir '+label}"><span class="dock-icon tint-${tint}">${icon(ic,23)}</span><span>${label}</span></button>`}).join('')}</div></div>
<div class="widgets-title"><div><div class="section-label-alone">WIDGETS <span class="line"></span></div><h2>Seu painel <span>em tempo real, quando conectado</span></h2></div><button class="secondary-link" data-action="open-customize">${icon('plus',16)} Adicionar widget</button></div>
<div class="widget-grid" id="widget-grid">${state.widgets.filter(w=>w.visible).map(w=>card(w.id,widgetContent(w.id))).join('')}</div><div class="board-foot">ACCIO HUB / STUDIO <span>·</span> Tudo aqui é seu para organizar.</div></div>`}
function innerPage(){const p=state.page;
const head=(title,kicker,extra='')=>`<div class="subhead"><div class="eyebrow">ACCIO HUB <span class="eyebrow-sep">/</span> ${esc(kicker)}</div><h1>${esc(title)}<span class="title-stop">.</span></h1></div>${extra}`;
if(p==='tasks'||p==='inbox'){return `<div class="inner-page">${head('Tarefas','PRODUTIVIDADE',`<button class="button" data-modal="task">${icon('plus',17)} Nova tarefa</button>`)}<div class="inner-block"><div class="block-top"><h2>Suas atividades</h2>${badge(`${state.tasks.filter(t=>!t.done).length} abertas`)}</div>${state.tasks.map(t=>taskRow(t,false)).join('')}<button class="add-row" data-modal="task">${icon('plus',16)} Adicionar tarefa</button></div></div>`}
if(p==='focus')return `<div class="inner-page">${head('Seu momento de foco','PRODUTIVIDADE')}<div class="inner-block focus-standalone">${widgetContent('focus')}<p>Uma sessão por vez, vinculável às suas tarefas no aplicativo definitivo.</p>${badge(`${state.focusRuns} sessão(ões) concluída(s) nesta prévia`)}</div></div>`;
if(p==='knowledge'){let n=state.notes.find(x=>x.id===Number(state.noteId))||state.notes[0];return `<div class="inner-page">${head('Conhecimento','BIBLIOTECA',`<button class="button" data-modal="note">${icon('plus',16)} Nova nota</button>`)}<div class="knowledge-layout"><div class="inner-block knowledge-sidebar"><div class="block-top"><h2>Vault de demonstração</h2></div>${state.notes.map(v=>`<button class="knowledge-file ${v.id===n?.id?'current':''}" data-note="${v.id}">${icon('book',16)} ${esc(v.title)}</button>`).join('')}<div class="caution">Nesta P0, as notas ficam apenas no navegador. Arquivos .md reais virão na implementação do Vault.</div></div><div class="inner-block knowledge-editor"><div class="block-top"><h2>${esc(n?.title||'Nota')}</h2>${badge('DEMO')}</div><textarea id="note-editor" data-edit-note="${n?.id||''}" spellcheck="false" aria-label="Conteúdo Markdown">${esc(n?.body||'')}</textarea></div></div></div>`}
if(p==='projects'){const d=projectDefs.find(x=>x.name===state.project)||projectDefs[0];return `<div class="inner-page">${head('Projetos','ORGANIZAÇÃO')}<div class="projects-board">${projectDefs.map(x=>`<button class="project-choice ${x.name===d.name?'chosen':''}" data-open-project="${esc(x.name)}"><span class="project-logo tint-${x.tint}">${icon(x.icon,25)}</span><strong>${esc(x.name)}</strong><small>${esc(x.description)}</small></button>`).join('')}</div><div class="inner-block"><div class="block-top"><h2>${esc(d.name)}</h2>${badge('ESPAÇO DE TRABALHO')}</div><p class="muted">${esc(d.description)}</p><div class="project-links"><button class="button tertiary" data-route="tasks">${icon('check',17)} Ver tarefas</button><button class="button tertiary" data-route="knowledge">${icon('book',17)} Ver notas</button><button class="button tertiary" data-route="focus">${icon('target',17)} Iniciar foco</button></div></div></div>`}
if(p==='settings')return `<div class="inner-page">${head('Personalização','SEU ESPAÇO')}<div class="inner-block">${settingsContents()}</div></div>`;
const descriptions={calendar:'Calendário e blocos de tempo entrarão na etapa funcional.',feed:'Notícias reais virão da API do AccioFeed existente.',backup:'Backups locais e Restic serão consultados em modo somente leitura.',email:'O resumo de e-mails exigirá integração autenticada com Gmail.'};
return `<div class="inner-page">${head(labels[p]||p,'INFORMAÇÕES')}<div class="inner-block unavailable"><span class="module-icon">${icon(nav.find(n=>n[0]===p)?.[2]||'grid',30)}</span><h2>Em preparação</h2><p>${esc(descriptions[p]||'Módulo planejado.')}</p>${badge('NENHUM DADO REAL CONECTADO','warn')}<br><button class="button tertiary" data-route="home">Voltar ao board</button></div></div>`}
function settingsContents(){return `<div class="setting-group"><h3>Plano de fundo</h3><div class="wallpaper-options">${[['northern','Aurora'],['ember','Pôr do sol'],['ocean','Azul profundo'],['graphite','Grafite']].map(([id,title])=>`<button class="wallpaper-swatch wall-${id} ${state.wallpaper===id?'active':''}" data-wallpaper="${id}"><span>${title}</span></button>`).join('')}</div></div><div class="setting-group"><h3>Preferências</h3><div class="setting-row"><span>Cor de destaque <small>Botões e seleções</small></span><input type="color" id="accent-color" value="${esc(state.accent)}" aria-label="Cor de destaque"></div><div class="setting-row"><span>Tema <small>Claro e escuro</small></span><select id="theme-select"><option value="dark" ${state.theme==='dark'?'selected':''}>Escuro</option><option value="light" ${state.theme==='light'?'selected':''}>Claro</option></select></div><div class="setting-row"><span>Accio Music <small>Barra global demonstrativa</small></span><input type="checkbox" id="music-visible" ${state.music?'checked':''}></div></div></div><div class="setting-group"><h3>Dock de aplicativos</h3><div class="widget-settings">${state.dockOrder.map((id,i)=>{const d=dock.find(x=>x[0]===id);return d?`<div class="setting-row"><label class="show-label"><input type="checkbox" data-dock-visible="${id}" ${state.dockHidden.includes(id)?'':'checked'}>${esc(d[1])}</label><button class="mini-control" data-dock-up="${id}" ${i===0?'disabled':''}>↑</button><button class="mini-control" data-dock-down="${id}" ${i===state.dockOrder.length-1?'disabled':''}>↓</button></div>`:''}).join('')}</div></div><div class="setting-group"><h3>Widgets</h3><div class="widget-settings">${state.widgets.map((w,i)=>`<div class="setting-row"><label class="show-label"><input type="checkbox" data-visible="${w.id}" ${w.visible?'checked':''}>${widgetDefs[w.id].title}</label><select data-span="${w.id}" aria-label="Tamanho de ${widgetDefs[w.id].title}">${[3,4,5,6,8,12].map(x=>`<option value="${x}" ${w.span===x?'selected':''}>${x}/12</option>`).join('')}</select><button class="mini-control" data-up="${w.id}" ${i===0?'disabled':''}>↑</button><button class="mini-control" data-down="${w.id}" ${i===state.widgets.length-1?'disabled':''}>↓</button></div>`).join('')}</div><button class="button tertiary" data-action="reset-widgets">Restaurar widgets sugeridos</button></div><p class="setting-note">As preferências ficam salvas neste navegador. Não altera seu Ubuntu, AccioFeed ou backups.</p>`}
function musicBar(){return !state.music?'':`<div class="music-zone"><div class="music-main"><span class="music-art tint-purple">${icon('music',18)}</span><div class="music-caption"><strong>Accio Music</strong><small>Escolha seu ambiente sonoro <span>· player demonstrativo</span></small></div><span class="music-waves"><i></i><i></i><i></i><i></i><i></i></span><div class="music-spacer"></div><span class="track-label">SEM ÁUDIO NESTA PRÉVIA</span><button class="music-button" data-action="music-info" title="Reprodução na fase de integração">${icon('play',16)}</button><button class="music-button" data-action="music-expand" aria-label="Expandir player">${icon('sliders',16)}</button></div>${state.musicExpanded?`<div class="music-expanded"><div><h3>Seu som. Seu ritmo.</h3><p>Na versão funcional: web rádios, favoritos e integração com Pomodoro. Nesta P0.3, o áudio ainda não está implementado.</p></div><button class="button tertiary" data-action="music-expand">Recolher</button></div>`:''}</div>`}
function dialog(){if(!state.modal)return '';const note=state.modal==='note';return `<div class="scrim" data-dismiss="modal"><form class="dialog" id="new-item"><div class="block-top"><h2>${note?'Capturar ideia':'Nova tarefa'}</h2><button type="button" class="mini-control" data-action="close-modal">${icon('x')}</button></div><label>Título<input name="title" placeholder="${note?'Dê um nome a sua nota':'O que precisa fazer?'}" required maxlength="120" autofocus></label><label>Projeto<select name="project">${['Pessoal',...projectDefs.map(p=>p.name)].map(p=>`<option>${esc(p)}</option>`).join('')}</select></label><p class="muted">Conteúdo demonstrativo: salvo no armazenamento do navegador.</p><button class="button" type="submit">${icon('plus',16)} Salvar ${note?'nota':'tarefa'}</button></form></div>`}
function drawer(){if(!state.drawer)return '';return `<div class="scrim" data-dismiss="drawer"><aside class="drawer"><div class="drawer-head"><div class="eyebrow">ACCIO STUDIO</div><h2>Deixe com a sua cara.</h2><button class="mini-control" data-action="close-customize">${icon('x')}</button></div>${settingsContents()}<button class="button drawer-done" data-action="close-customize">Concluir personalização</button></aside></div>`}
function searchModal(){if(!state.search)return '';let q=state.query.trim().toLowerCase();const entries=[...nav.map(([id,label,ic])=>({type:'page',id,label,icon:ic,sub:'Aplicativo'})),...state.notes.map(n=>({type:'note',id:n.id,label:n.title,icon:'book',sub:'Nota · '+n.project})),...state.tasks.map(t=>({type:'task',id:t.id,label:t.title,icon:'check',sub:'Tarefa · '+t.project}))].filter(x=>!q||x.label.toLowerCase().includes(q)||x.sub.toLowerCase().includes(q)).slice(0,9);return `<div class="scrim" data-dismiss="search"><div class="search-modal"><div class="search-field">${icon('search',21)}<input id="command-search" autocomplete="off" placeholder="Buscar apps, tarefas e notas..." value="${esc(state.query)}"><span>ESC</span></div><div class="search-results">${entries.length?entries.map(x=>`<button data-result="${x.type}:${x.id}">${icon(x.icon,18)}<span>${esc(x.label)}<small>${esc(x.sub)}</small></span>${icon('chevron',14)}</button>`).join(''):'<p>Nenhum resultado encontrado.</p>'}</div></div></div>`}
function render(){document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.wallpaper=state.wallpaper;document.documentElement.style.setProperty('--accent',state.accent);document.title=`${labels[state.page]||'Accio Hub'} · Accio Hub P0.3`;
$('#app').innerHTML=`<div class="shell"><aside class="rail"><button class="brand-glyph" data-route="home" aria-label="Accio Hub início">a<span class="brand-dot"></span></button><div class="rail-divider"></div><nav class="rail-icons" aria-label="Aplicativos">${nav.map(([id,name,ic],i)=>`<button class="rail-icon ${state.page===id?'active':''}" title="${name}" aria-label="${name}" data-route="${id}">${icon(ic,21)}<span>${name}</span></button>`).join('')}</nav><div class="rail-bottom"><button class="rail-icon ${state.page==='settings'?'active':''}" title="Configurações" data-route="settings">${icon('settings',21)}<span>Configurações</span></button><div class="rail-avatar" aria-label="Espaço pessoal">G</div></div></aside><div class="workspace"><header class="headbar"><div class="head-left"><button class="mobile-brand" data-route="home">a<span> ACCIO HUB</span></button><div class="wordmark">ACCIO<span> / </span>HUB</div><div class="head-path">${icon('chevron',14)} ${esc(labels[state.page]||'Hoje')}</div></div><div class="head-right"><button class="command-button" data-action="search">${icon('search',17)} <span>Buscar no seu espaço</span> <kbd>Ctrl K</kbd></button><span class="header-divider"></span><span class="live-rail-dot"></span><span class="mini-time" data-nav-time>${timeFmt()}</span><button class="head-icon" data-modal="note" title="Capturar ideia">${icon('edit',19)}</button><button class="head-icon" data-action="open-customize" title="Personalizar">${icon('sliders',20)}</button></div></header>${musicBar()}<main class="viewport">${state.page==='home'?board():innerPage()}</main></div></div>${drawer()}${dialog()}${searchModal()}`;refreshLive();}
function go(page){state.page=page;state.drawer=false;state.search=false;state.modal=null;persist();location.hash='#/'+page;render();$('.viewport')?.scrollTo(0,0)}
function updateFocus(){syncFocus();for(const x of document.querySelectorAll('[data-timer]'))x.textContent=fmt(state.focusLeft);for(const x of document.querySelectorAll('.dial'))x.style.setProperty('--p',`${(1-state.focusLeft/(state.focusMin*60))*100}%`)}
function refreshLive(){document.querySelectorAll('[data-nav-time],[data-now-time]').forEach(n=>n.textContent=timeFmt());document.querySelectorAll('[data-now-date]').forEach(n=>n.textContent=dateFmt());for(const x of document.querySelectorAll('[data-timer]'))x.textContent=fmt(state.focusLeft)}
function action(id){if(id==='edit'){state.edit=!state.edit}else if(id==='open-customize'){state.drawer=true;state.edit=false}else if(id==='close-customize'){state.drawer=false}else if(id==='focus-toggle'){syncFocus();state.focusRunning=!state.focusRunning;state.focusEnd=state.focusRunning?Date.now()+state.focusLeft*1000:null}else if(id==='focus-reset'){state.focusRunning=false;state.focusEnd=null;state.focusLeft=state.focusMin*60}else if(id==='focus-length'){state.focusMin=state.focusMin===25?45:25;state.focusLeft=state.focusMin*60;state.focusRunning=false;state.focusEnd=null}else if(id==='music-expand'){state.musicExpanded=!state.musicExpanded}else if(id==='music-info'){window.alert('A reprodução ainda não foi implementada na P0.3. O player está aqui para validar a interface.') ;return}else if(id==='close-modal'){state.modal=null}else if(id==='search'){state.search=true;state.query=''}else if(id==='reset-widgets'){state.widgets=defaultWidgets.map(x=>({...x}));}persist();render();if(id==='search')$('#command-search')?.focus();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-route],[data-modal],[data-note],[data-open-project],[data-zoom],[data-up],[data-down],[data-dock-up],[data-dock-down],[data-result]');if(!el){if(e.target.classList.contains('scrim')){state.drawer=false;state.modal=null;state.search=false;render()}return}const d=el.dataset;if(d.route){go(d.route);return}if(d.action){action(d.action);return}if(d.modal){state.modal=d.modal;render();$('.dialog input[name="title"]')?.focus();return}if(d.note){state.noteId=Number(d.note);go('knowledge');return}if(d.openProject){state.project=d.openProject;go('projects');return}if(d.zoom){const w=state.widgets.find(x=>x.id===d.zoom);w.span=w.span>=12?3:w.span===8?12:w.span===6?8:w.span===5?6:w.span===4?5:4;persist();render();return}if(d.up||d.down){const id=d.up||d.down,i=state.widgets.findIndex(x=>x.id===id),j=i+(d.up?-1:1);if(j>=0&&j<state.widgets.length)[state.widgets[i],state.widgets[j]]=[state.widgets[j],state.widgets[i]];persist();render();return}if(d.dockUp||d.dockDown){const id=d.dockUp||d.dockDown,i=state.dockOrder.indexOf(id),j=i+(d.dockUp?-1:1);if(j>=0&&j<state.dockOrder.length)[state.dockOrder[i],state.dockOrder[j]]=[state.dockOrder[j],state.dockOrder[i]];persist();render();return}if(d.result){const [kind,id]=d.result.split(':');state.search=false;if(kind==='page')go(id);else if(kind==='note'){state.noteId=Number(id);go('knowledge')}else go('tasks');return}});
// Fallback para checkboxes em browsers que atrasam o evento change durante um rerender.
document.addEventListener('click',e=>{if(!e.target.matches('input[data-task]'))return;const id=Number(e.target.dataset.task),checked=e.target.checked;queueMicrotask(()=>{const task=state.tasks.find(t=>t.id===id);if(task&&task.done!==checked){task.done=checked;persist();render()}})});
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.task){const t=state.tasks.find(x=>x.id===Number(d.task));if(t)t.done=e.target.checked;persist();render();return}if(d.visible){state.widgets.find(x=>x.id===d.visible).visible=e.target.checked;persist();render();return}if(d.dockVisible){if(e.target.checked)state.dockHidden=state.dockHidden.filter(x=>x!==d.dockVisible);else if(!state.dockHidden.includes(d.dockVisible))state.dockHidden.push(d.dockVisible);persist();render();return}if(d.span){state.widgets.find(x=>x.id===d.span).span=Number(e.target.value);persist();render();return}if(d.wallpaper){state.wallpaper=d.wallpaper;persist();render();return}if(e.target.id==='theme-select'){state.theme=e.target.value;persist();render()}if(e.target.id==='music-visible'){state.music=e.target.checked;persist();render()}if(e.target.id==='accent-color'){state.accent=e.target.value;persist();render()}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-wallpaper]');if(el){state.wallpaper=el.dataset.wallpaper;persist();render()}});
document.addEventListener('input',e=>{if(e.target.id==='note-editor'){let n=state.notes.find(x=>x.id===Number(e.target.dataset.editNote));if(n){n.body=e.target.value;persist()}}if(e.target.id==='command-search'){state.query=e.target.value;const selection=e.target.selectionStart;render();const input=$('#command-search');input?.focus();input?.setSelectionRange(selection,selection)}if(e.target.id==='accent-color'){document.documentElement.style.setProperty('--accent',e.target.value)}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-item')return;e.preventDefault();let d=new FormData(e.target),title=String(d.get('title')||'').trim(),project=String(d.get('project')||'Pessoal');if(!title)return;const id=Date.now();if(state.modal==='note'){state.notes.unshift({id,title,project,body:`# ${title}\n\n`});state.noteId=id;state.modal=null;go('knowledge')}else{state.tasks.unshift({id,title,project,done:false,priority:'Normal'});state.modal=null;go('tasks')}persist()});
let dragged=null; let draggedDock=null;
document.addEventListener('dragstart',e=>{if(!state.edit)return;const k=e.target.closest('[data-dock]');if(k){draggedDock=k.dataset.dock;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain','dock:'+draggedDock);k.classList.add('dragging');return}const w=e.target.closest('[data-widget]');if(!w)return;dragged=w.dataset.widget;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged);w.classList.add('dragging')});
document.addEventListener('dragover',e=>{const k=e.target.closest('[data-dock]');if(state.edit&&draggedDock&&k&&k.dataset.dock!==draggedDock){e.preventDefault();e.dataTransfer.dropEffect='move';k.classList.add('drag-over');return}const w=e.target.closest('[data-widget]');if(state.edit&&dragged&&w&&w.dataset.widget!==dragged){e.preventDefault();e.dataTransfer.dropEffect='move';w.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const k=e.target.closest('[data-dock]');if(k)k.classList.remove('drag-over');const w=e.target.closest('[data-widget]');if(w)w.classList.remove('drag-over')});
document.addEventListener('drop',e=>{if(!state.edit)return;const k=e.target.closest('[data-dock]');if(k&&draggedDock){e.preventDefault();const i=state.dockOrder.indexOf(draggedDock),j=state.dockOrder.indexOf(k.dataset.dock);if(i>=0&&j>=0&&i!==j){const [x]=state.dockOrder.splice(i,1);state.dockOrder.splice(j,0,x);persist()}draggedDock=null;render();return}const w=e.target.closest('[data-widget]');if(!dragged||!w)return;e.preventDefault();const i=state.widgets.findIndex(x=>x.id===dragged),j=state.widgets.findIndex(x=>x.id===w.dataset.widget);if(i>=0&&j>=0&&i!==j){const [x]=state.widgets.splice(i,1);state.widgets.splice(j,0,x);persist()}dragged=null;render()});
document.addEventListener('dragend',()=>{draggedDock=null;dragged=null;document.querySelectorAll('.dragging,.drag-over').forEach(el=>el.classList.remove('dragging','drag-over'))});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(state.search||state.drawer||state.modal){state.search=false;state.drawer=false;state.modal=null;render()}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();action('search')}if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='n'){e.preventDefault();state.modal='note';render();$('.dialog input')?.focus()}});
window.addEventListener('hashchange',()=>{let r=location.hash.replace('#/','').split('/')[0];if(labels[r]&&r!==state.page){state.page=r;persist();render()}});
setInterval(()=>{if(state.focusRunning)updateFocus();refreshLive()},1000);
let initial=location.hash.replace('#/','').split('/')[0];if(labels[initial])state.page=initial;
render();
